SELECT e.Fname || ' ' || e.Minit || ' ' || e.Lname AS full_name
FROM employee e
WHERE (
    SELECT COUNT(*) FROM employee sub WHERE sub.Super_ssn = e.Ssn
) >= 2
AND (
    SELECT COALESCE(SUM(Hours), 0) FROM works_on w WHERE w.Essn = e.Ssn
) > (
    SELECT AVG(Hours) FROM works_on WHERE Pno = 1
);
